(function(root){'use strict';
const missions=[
 {id:'recovery',title:'Rescue the workstation',area:'Systems · recovery',lesson:'troubleshooting',goal:'Restore a fictional workstation while preserving its documents.',badge:'Recovery detective',initial:'Boot failed after a driver update. Documents are still present. No hardware fault is established.',steps:[
 ['inspect','Inspect boot evidence','Log: driver update immediately preceded boot failure; storage diagnostic passed.','Evidence supports investigating the update, not wiping the disk.'],
 ['protect','Verify the document backup','Backup inventory: 12 of 12 synthetic documents; sample restore matches.','Check recoverability before changing the failing system.'],
 ['rollback','Roll back the simulated driver','Previous driver selected. Boot has not yet been tested.','A change is a hypothesis, not proof of recovery.'],
 ['reboot','Test a simulated reboot','Desktop loaded. Documents and applications still need checks.','Boot success alone does not prove data and application health.'],
 ['verify','Verify documents and application','12 of 12 documents match; the sample application opens. Recovery verified.','You tested both service restoration and preservation of user data.']],
 distractions:[['wipe','Wipe the fictional disk','Wiping would discard the documents. No destructive change was applied; investigate and preserve data instead.'],['declare','Declare fixed without testing','No success awarded: a claim is not evidence. Complete reboot and data/application verification.']]},
 {id:'network',title:'Bring the help desk online',area:'Networking · diagnosis',lesson:'ip-subnets',goal:'Find why a fictional workstation can reach a server by address but not by name.',badge:'Packet detective',initial:'The internal help page fails by name. A synthetic direct-address request succeeds.',steps:[
 ['inspect','Compare address and name tests','Address test succeeds; name lookup times out. Link and address reachability work in this fixture.','Different tests isolate different parts of the request path.'],
 ['config','Inspect resolver configuration','Configured resolver: 192.0.2.99. The fixture inventory specifies 192.0.2.53.','Compare observed configuration with the approved fictional baseline.'],
 ['repair','Apply the fixture resolver baseline','Resolver set to 192.0.2.53 in simulation memory only.','Fix the identified mismatch; do not disable unrelated protections.'],
 ['verify','Retest name lookup and help page','Name resolves and help page returns the expected fixture content.','Verify the original user-visible symptom, not only the setting.']],
 distractions:[['firewall','Disable all firewalls','Not applied: broad security changes are unsupported by this evidence.'],['declare','Mark online without retesting','No success awarded: test name resolution and the original help page.']]},
 {id:'data',title:'Repair the double-counted report',area:'Data · validation',lesson:'data-model',goal:'Correct a fictional revenue report without deleting source records.',badge:'Data guardian',initial:'Order A = $20; order B = $30. Joining two tags per order produced an incorrect total of $100.',steps:[
 ['inspect','Inspect report rows','A/red $20, A/blue $20, B/red $30, B/blue $30. Source has two orders, not four.','A one-to-many join changes row counts and can multiply measures.'],
 ['grain','Identify the intended grain','Revenue is per unique order ID. Tags are a separate one-to-many dimension.','Choose the unit being measured before selecting an aggregation.'],
 ['repair','Aggregate the original order table','Order A $20 + order B $30 = $50. Original orders and tags preserved.','Repair the report logic rather than deleting legitimate tags.'],
 ['verify','Validate total and source counts','Total $50; two original orders and four tag links retained. Validation passed.','Verify correctness and preservation together.']],
 distractions:[['delete','Delete half the tag records','Not applied: legitimate tags would be lost; fix aggregation at the intended grain.'],['distinct','Sum distinct price values','Not applied: different orders can have equal prices. Distinct prices are not distinct orders.']]}
];
const byId=id=>missions.find(m=>m.id===id), fresh=id=>({id,step:0,attempts:0,log:[],complete:false});
function advance(state,action){const m=byId(state.id);if(!m)throw Error('Unknown simulation');const s={...state,log:state.log.slice()};if(s.complete)return s;const step=m.steps[s.step];const wrong=m.distractions.find(x=>x[0]===action);const known=m.steps.find(x=>x[0]===action);if(!wrong&&!known)return s;s.attempts++;let message,accepted=false;if(action===step[0]){accepted=true;message=step[2]+' '+step[3];s.step++;s.complete=s.step===m.steps.length;}else message=wrong?wrong[2]:'That action needs earlier evidence or preservation checks. Try the next investigation step first.';s.log.push({action,accepted,message});s.log=s.log.slice(-100);return s;}
const emptyRewards=()=>({schema:1,completed:[]});
function validateRewards(value){if(!value||value.schema!==1||!Array.isArray(value.completed)||value.completed.length>missions.length||value.completed.some(id=>typeof id!=='string'||!byId(id))||new Set(value.completed).size!==value.completed.length)throw Error('Invalid simulation progress');return {schema:1,completed:value.completed.slice()};}
function award(rewards,state){const next=validateRewards(rewards);if(state.complete&&state.step===byId(state.id)?.steps.length&&!next.completed.includes(state.id))next.completed.push(state.id);return next;}
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sessions=new Map();let selected='recovery',rewards=emptyRewards(),loaded=false,saveIssue='',celebrations=true;
const key='athena-simulation-award-v1:';
function load(){if(loaded)return;loaded=true;try{for(const m of missions){const raw=root.localStorage.getItem(key+m.id);if(raw!==null){if(raw.length>128)throw Error('Oversized reward');const saved=validateRewards(JSON.parse(raw));if(saved.completed.length!==1||saved.completed[0]!==m.id)throw Error('Mismatched reward');rewards.completed.push(m.id);}}}catch{saveIssue='Saved simulation rewards could not be read. Session practice still works; existing storage will not be overwritten.';}}
function render(host){load();const m=byId(selected),s=sessions.get(selected)||fresh(selected);sessions.set(selected,s);host.innerHTML=`<div class="notice"><strong>Fictional simulation, not a real computer.</strong> All actions use fixed teaching data in this page. No terminals, devices, networks or cloud resources are accessed. This does not certify practical mastery or replace version-matched real practice.</div><div class="sim-summary panel"><strong>${rewards.completed.length*100} simulation XP · ${rewards.completed.length}/${missions.length} badges</strong><p>100 XP and one badge for each first verified mission completion. Replays are welcome, with no duplicate reward. Separate from lesson XP; no roguelite gameplay or GameSync rewards are connected yet.</p><label><input type="checkbox" data-sim-motion ${celebrations?'checked':''}> Success celebrations (no sound; respects reduced motion)</label><p class="meta">Badges stay in this browser when storage is available. Active missions and logs last only for this open page; export a receipt to keep them.</p>${saveIssue?`<p role="status">${escape(saveIssue)}</p>`:''}</div><div class="filters" aria-label="Training missions">${missions.map(x=>`<button data-sim-select="${x.id}" aria-pressed="${x.id===selected}">${escape(x.title)}${rewards.completed.includes(x.id)?' ✓':''}</button>`).join('')}</div><section class="panel sim-mission" aria-labelledby="sim-title"><span class="tag">${escape(m.area)}</span><h2 id="sim-title" tabindex="-1">${escape(m.title)}</h2><p>${escape(m.goal)}</p><progress value="${s.step}" max="${m.steps.length}" aria-label="Verified simulation steps"></progress><p>${s.step}/${m.steps.length} verified steps · ${s.attempts} actions tried</p><div class="sim-screen"><span aria-hidden="true">${s.complete?'✦':'▣'}</span><strong>${s.complete?'Mission verified':s.step?'Investigation in progress':'Incident reported'}</strong><p>${escape(s.step?m.steps[s.step-1][2]:m.initial)}</p></div><div class="sim-actions" role="group" aria-label="Choose a simulated action">${[...m.steps,...m.distractions].map(x=>`<button class="quiet" data-sim-action="${x[0]}" ${s.complete?'disabled':''}>${escape(x[1])}</button>`).join('')}</div><div id="sim-feedback" role="status" aria-live="polite" tabindex="-1">${s.log.length?escape(s.log.at(-1).message):'Choose an action. You can try a hypothesis, inspect evidence, and recover from mistakes.'}</div>${s.complete?`<div class="sim-victory"><strong>✦ ${escape(m.badge)} earned</strong><p>You verified the outcome, not just the change. Explain the evidence in your own words, then try another mission.</p></div>`:''}<div class="actions"><button class="quiet" data-sim-reset>Restart this mission</button><button class="quiet" data-sim-export>Export simulation receipt</button><a class="button secondary" href="#foundations">Explore supporting lessons</a></div><details><summary>Action evidence (${s.log.length} retained)</summary><ol>${s.log.map(x=>`<li><strong>${x.accepted?'Verified step':'Try again'}:</strong> ${escape(x.message)}</li>`).join('')}</ol></details></section>`;
 host.onclick=e=>{const b=e.target.closest('button');if(!b||!host.contains(b)||b.disabled)return;if(b.dataset.simSelect){selected=b.dataset.simSelect;render(host);host.querySelector('#sim-title').focus();}else if(b.hasAttribute('data-sim-reset')){sessions.set(selected,fresh(selected));render(host);host.querySelector('#sim-title').focus();}else if(b.dataset.simAction){const before=sessions.get(selected),next=advance(before,b.dataset.simAction);sessions.set(selected,next);if(next.complete&&!before.complete){rewards=award(rewards,next);if(!saveIssue)try{root.localStorage.setItem(key+next.id,JSON.stringify({schema:1,completed:[next.id]}));}catch{saveIssue='Reward earned for this session only: browser storage is unavailable. Export a receipt before closing.';}}render(host);host.querySelector('#sim-feedback').focus();if(next.complete&&!before.complete&&celebrations&&!root.matchMedia('(prefers-reduced-motion: reduce)').matches){const fx=root.document.createElement('div');fx.className='sim-fireworks';fx.setAttribute('aria-hidden','true');fx.textContent='✧ ✦ ✧ ✺ ✧ ✦ ✧';host.querySelector('.sim-victory').append(fx);}}else if(b.hasAttribute('data-sim-export')){const receipt={schema:1,kind:'athena-fictional-training-receipt',scenarioVersion:1,mission:selected,state:sessions.get(selected),rewards,limitations:['Self-reported browser simulation; editable locally, not tamper-proof evidence','Not a certification, real OS repair, or a game unlock']};const url=URL.createObjectURL(new Blob([JSON.stringify(receipt,null,2)+'\n'],{type:'application/json'}));const a=root.document.createElement('a');a.href=url;a.download='athena-simulation-'+selected+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}};
 host.onchange=e=>{if(e.target.hasAttribute('data-sim-motion'))celebrations=e.target.checked;};
}
const api={missions,fresh,advance,emptyRewards,validateRewards,award,mount:render};if(typeof module==='object'&&module.exports)module.exports=api;else root.AthenaSimulations=api;
})(typeof globalThis==='object'?globalThis:this);
